def apply_cross_transform(grid):
    """Transform: Single isolated pixels become 5-cell crosses; multi-cell groups stay as-is"""
    rows, cols = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    # Process in order, track processed cells
    processed = set()

    for r in range(rows):
        for c in range(cols):
            if (r,c) in processed or grid[r][c] == 5: continue

            val = grid[r][c]

            # Check if starting new component
            if c > 0 and grid[r][c-1] == val:
                continue
            if r > 0 and grid[r-1][c] == val:
                continue

            # Find component using 4-connectivity
            comp = []
            queue = [(r,c)]
            visited = {(r,c)}

            idx = 0
            while idx < len(queue):
                cr, cc = queue[idx]
                idx += 1
                comp.append((cr,cc))

                for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0<=nr<rows and 0<=nc<cols and grid[nr][nc]==val and (nr,nc) not in visited:
                        visited.add((nr,nc))
                        queue.append((nr,nc))

            # Mark all component cells as processed
            for pr,pc in comp:
                processed.add((pr,pc))

            # Apply transformation
            if len(comp) == 1:
                # Single pixel: become cross
                center_r, center_c = r, c
                offsets = [(0,0), (-1,0), (1,0), (0,-1), (0,1)]
                for dr, dc in offsets:
                    rr, cc = center_r + dr, center_c + dc
                    if 0 <= rr < rows and 0 <= cc < cols:
                        result[rr][cc] = val
            else:
                # Multi-cell: keep as-is
                pass

    return result

